import assert from 'node:assert/strict';
import { hostTeamSelectionKey } from '../../src/features/agent-backend/contracts/teamSelection.ts';
import { desktopJsLiteral } from './desktop-ui-controls.ts';

/** Read current owner/surface from the existing React dialog; return its actual input ID, never synthesize one. */
export function desktopTaskCommentInputExpression(handleId: string, taskId: string): string {
  assert.ok(handleId && taskId);
  return `(() => {
    const owner=${desktopJsLiteral(hostTeamSelectionKey(handleId))},taskId=${desktopJsLiteral(taskId)};
    const currentFiber=node=>{
      const key=Object.keys(node).find(key=>key.startsWith('__reactFiber$')),fiber=key?node[key]:null;
      for(const candidate of [fiber,fiber?.alternate]){
        if(!candidate)continue;let root=candidate,depth=0;
        while(root.return&&depth++<256)root=root.return;
        if(!root.return&&root.stateNode?.current===root)return candidate;
      }
      return null;
    };
    const matches=[];
    for(const dialog of document.querySelectorAll('[role="dialog"]')){
      if(!dialog.getClientRects().length)continue;
      const controllers=new Set();
      for(let fiber=currentFiber(dialog),depth=0;fiber&&depth<128;fiber=fiber.return,depth++){
        const p=fiber.memoizedProps,c=p?.sessionController,i=c?.identity;
        if(p?.open===true&&p.teamName===owner&&p.task?.id===taskId&&i?.teamName===owner&&i.taskId===taskId&&
          typeof i.contextId==='string'&&i.contextId&&typeof c.surfaceId==='string'&&c.surfaceId&&
          c.isOwner===true&&c.session?.ownerSurfaceId===c.surfaceId)controllers.add(c);
      }
      if(controllers.size!==1)continue;const controller=[...controllers][0],identity=controller.identity;
      for(const input of dialog.querySelectorAll('textarea')){
        if(!input.id||input.disabled||!input.getClientRects().length)continue;
        for(let fiber=currentFiber(input),depth=0;fiber&&depth<128;fiber=fiber.return,depth++){
          const p=fiber.memoizedProps;
          if(p?.controller!==controller||p.contextId!==identity.contextId||p.teamName!==owner||p.taskId!==taskId||p.surfaceId!==controller.surfaceId)continue;
          if([...document.querySelectorAll('textarea')].filter(e=>e.id===input.id).length!==1)throw Error('duplicate current Task comment input ID');
          matches.push({teamName:owner,taskId,identity:{contextId:identity.contextId,teamName:identity.teamName,taskId:identity.taskId},
            surfaceId:controller.surfaceId,inputId:input.id,commentText:controller.session.commentText,
            submitPending:controller.session.submitPending,submitError:controller.session.submitError,
            ownerRevision:controller.session.ownerRevision,partRevisions:{commentText:controller.session.partRevisions.commentText,pendingAttachments:controller.session.partRevisions.pendingAttachments},
            pendingPreparationCount:controller.session.pendingAttachmentPreparationIds.length,canSubmit:controller.canSubmit,attachmentError:controller.attachmentError,
            pendingAttachmentCount:controller.session.pendingAttachments.length,canEditNow:controller.canEditNow?.()===true,canResolveClarification:controller.canResolveClarification===true,selector:'[role="dialog"] textarea[id='+JSON.stringify(input.id)+']'});
          break;
        }
      }
    }
    if(matches.length>1)throw Error('ambiguous current Task comment owner/surface');
    return matches[0]??null;
  })()`;
}

/** Observe the original assignment, its clarification control, or later in-progress comment stage. */
export function desktopTaskBoardAssignmentReadyExpression(
  handleId: string,
  taskId: string,
  captured: { contextId: string; surfaceId: string },
  stage?: 'in-progress-comment' | 'clarification' | 'clarification-cleared'
): string {
  assert.ok(captured.contextId && captured.surfaceId);
  return `(async()=>{
    const {isTeamDataRefreshPending}=await import('/store/slices/teamSlice.ts');
    const {captureTaskDetailReadScope,isTaskDetailTeamUnavailable}=await import('/store/team/taskDetailReadAuthority.ts');
    const owner=${desktopTaskCommentInputExpression(handleId, taskId)};
    if(!owner||!owner.canEditNow||owner.identity.contextId!==${desktopJsLiteral(captured.contextId)}||owner.surfaceId!==${desktopJsLiteral(captured.surfaceId)})return null;
    const s=window.__agentTeamsDevStore.getState(),i=owner.identity;
    const detail=s.taskDetailById[JSON.stringify([i.contextId,i.teamName,i.taskId])];
    if(s.isContextSwitching||s.activeContextId!==i.contextId||s.selectedTeamName!==i.teamName||
      !detail||detail.identity.contextId!==i.contextId||detail.identity.teamName!==i.teamName||detail.identity.taskId!==i.taskId||
      detail.phase!=='ready'||(detail.loading&&${stage !== 'clarification'})||detail.refreshPending||detail.full?.id!==i.taskId||detail.full.owner!=='alice'||
      isTeamDataRefreshPending(i.teamName,window.__agentTeamsDevStore.getState)||
      isTaskDetailTeamUnavailable(s,i.teamName,captureTaskDetailReadScope(i.teamName,i.contextId)))return null;
    ${stage === 'clarification' ? `
      const key=JSON.stringify([i.contextId,i.teamName,i.taskId]),session=s.taskDetailSessionById?.[key];
      if(owner.canResolveClarification!==true||!session||session.ownerSurfaceId!==owner.surfaceId||
        session.ownerRevision!==owner.ownerRevision||detail.error!==null||detail.deletionIntent!==null||
        detail.full.needsClarification!=='user'||detail.full.deletedAt||detail.full.status==='deleted')return null;
      if(detail.loading){
        const token=detail.fullToken,scope=captureTaskDetailReadScope(i.teamName,i.contextId);
        if(!token||token.resource!=='full'||token.key!=='full:'+key||!token.scope||
          token.scope.contextId!==scope.contextId||token.scope.teamName!==scope.teamName||
          token.scope.contextEpoch!==scope.contextEpoch||token.scope.teamStateEpoch!==scope.teamStateEpoch)return null;
      }
    ` : stage === 'clarification-cleared' ? `
      const key=JSON.stringify([i.contextId,i.teamName,i.taskId]),session=s.taskDetailSessionById?.[key];
      if(!session||session.ownerSurfaceId!==owner.surfaceId||session.ownerRevision!==owner.ownerRevision||
        detail.loading!==false||detail.refreshPending!==false||detail.error!==null||detail.deletionIntent!==null||
        detail.full.needsClarification!==undefined||detail.full.deletedAt||detail.full.status==='deleted')return null;
    ` : ''}
    const input=document.getElementById(owner.inputId),dialog=input?.closest('[role="dialog"]');
    const triggers=dialog?.querySelectorAll('button[role="combobox"]');
    ${stage === 'in-progress-comment'
      ? "if(detail.full.status!=='in_progress'||triggers?.length!==0)return null;"
      : "if(triggers?.length!==1||triggers[0].disabled||triggers[0].getAttribute('aria-expanded')!=='false'||triggers[0].textContent.trim()!=='alice')return null;"}
    ${stage === 'clarification-cleared' ? `
      const elements = [...dialog.querySelectorAll('button')].filter(e => {
        const r=e.getBoundingClientRect(); return r.width>0&&r.height>0&&e.textContent.trim()==='Close';
      });
      if(elements.length!==1)return {unavailableTarget:true,matches:Math.min(elements.length,256)};
      const e=elements[0], r=e.getBoundingClientRect(), x=r.x+r.width/2,y=r.y+r.height/2;
      const hit=document.elementFromPoint(x,y), disabled=e.matches(':disabled');
      if(!hit||!(hit===e||e.contains(hit))||disabled)return {
        unavailableTarget:true,matches:1,disabled,ariaDisabled:e.getAttribute('aria-disabled')==='true',
        pointerEventsNone:getComputedStyle(e).pointerEvents==='none',
        centerInViewport:x>=0&&y>=0&&x<innerWidth&&y<innerHeight,hitPresent:Boolean(hit)
      };
      return {x,y,text:e.textContent.trim().slice(0,300),tag:e.tagName};
    ` : 'return owner;'}
  })()`;
}

/** Close the original assigned Task only after its current owner and cleared detail are ready. */
export function clickDesktopTaskBoardClearedClose(
  ui: { clickExpression(expression: string, label: string, selector?: string, text?: string): Promise<void> },
  handleId: string,
  taskId: string,
  captured: { contextId: string; surfaceId: string }
): Promise<void> {
  return ui.clickExpression(
    desktopTaskBoardAssignmentReadyExpression(handleId, taskId, captured, 'clarification-cleared'),
    'close original Task detail',
    '[role="dialog"] button',
    'Close'
  );
}

import { runDesktopTaskBoardAttachmentsUi } from './desktop-task-board-attachments-ui.ts';
import assert from 'node:assert/strict';
import { mkdir, readFile, readdir, realpath, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { performance } from 'node:perf_hooks';

import { createTeamController } from '../../packages/legacy-agent-host/dist/adapters/team/ControllerAdapter.js';
import { readDesktopTaskBoardGroupSnapshot } from './desktop-task-board-group-page-read.ts';
import { fileDigest } from './desktop-backend-fixture.ts';
import {
  clickDesktopTaskBoardClearedClose,
  desktopTaskBoardAssignmentReadyExpression,
  desktopTaskCommentInputExpression,
} from './desktop-task-comment-input-target.ts';
import { createDesktopUiControls, desktopJsLiteral } from './desktop-ui-controls.ts';
import type { UiCdpPort } from './desktop-ui-controls.ts';

const teamName = 'test-desktop-backend';
const record = (value: unknown): Record<string, unknown> => {
  assert.ok(value && typeof value === 'object' && !Array.isArray(value));
  return value as Record<string, unknown>;
};
const json = async (path: string) => record(JSON.parse(await readFile(path, 'utf8')));
const pause = () => new Promise<void>((done) => setTimeout(done, 100));

/** Existing Create, assignee, clarification and sortable card controls; offline TEST owner only. */
export async function runDesktopTaskBoardUiSmoke(
  cdp: UiCdpPort,
  options: {
    root: string;
    repo: string;
    handleId: string;
    seed: {
      taskId: string;
      subject: string;
      commandId: string;
      group?: { groupChatId: string; name: string; commandId: string };
    };
    assertOwnedRenderer(): void;
    evidence: Record<string, unknown>;
  }
): Promise<void> {
  assert.equal(await realpath(options.root), options.root);
  assert.match(basename(options.root), /^TEST-desktop-backend-/);
  const profile = await json(join(options.root, 'host-profile.json'));
  assert.equal(record(profile.owner).storageRoot, join(options.root, 'hoststore'));
  assert.equal(profile.principalId, 'TEST-human');
  assert.equal(profile.runtime, undefined, 'this flow never starts a native provider');
  const taskDirectory = join(options.root, 'hoststore/tasks', teamName);
  const teamDirectory = join(options.root, 'hoststore/teams', teamName);
  const commandDirectory = join(teamDirectory, '.host-owner/commands');
  const task = (id: string) => json(join(taskDirectory, `${id}.json`));
  const rows = async (directory: string) => {
    const names = (await readdir(directory)).filter((name) => /^[A-Za-z0-9_-]+\.json$/.test(name));
    assert.ok(names.length <= 128, 'bounded TEST product census');
    return Promise.all(names.sort().map((name) => json(join(directory, name))));
  };
  const group = options.seed.group;
  assert.ok(group, 'the two original board modes require their canonical group seed');
  const originalGroupReceipts = (await rows(commandDirectory)).filter(
    (row) => row.family === 'group-chat'
  );
  assert.equal(originalGroupReceipts.length, group ? 1 : 0);
  if (group) {
    const original = originalGroupReceipts[0]!;
    assert.equal(original.commandId, group.commandId);
    assert.equal(original.principalId, 'TEST-human');
    assert.equal(original.phase, 'completed');
    assert.equal(record(original.request).operation, 'create');
    assert.equal(record(original.request).id, group.groupChatId);
    assert.equal(record(original.response).id, group.groupChatId);
  }
  const commands = async () => {
    const all = await rows(commandDirectory);
    assert.deepEqual(
      all.filter((row) => row.family === 'group-chat'),
      originalGroupReceipts,
      'the one original fixture group receipt is retained separately and never mutated'
    );
    return all.filter((row) => row.family !== 'group-chat');
  };
  const steps: Record<string, unknown>[] = [];
  const step = (row: Record<string, unknown>) =>
    steps.push({ monotonicMs: Math.round(performance.now()), ...row });
  const proof: Record<string, unknown> = {
    status: 'INCOMPLETE',
    steps,
    scope:
      'Original Create Task dependency picker, Task assignee/Mark resolved, sortable TODO cards and blocked Start/Complete controls; offline canonical Host persistence',
    qaInventory: [
      'Create dependency through original optional fields; reciprocal canonical graph and visible blocker',
      'Original Group chat filter supplies Create Task association; exact receipt/snapshot and renderer reload retain it',
      'Change assignee through existing Radix MemberSelect; retained captured owner',
      'TEST API sets clarification because no set control exists; original Mark resolved clears it',
      'Columns/Manual controls and one trusted pointer drag change canonical column order',
      'Blocked Start refuses unresolved dependency; exact detached canonical oracle; same control succeeds after actual blocker Complete',
      'Renderer reload retains original task IDs, assignment, clarification and order without new commands',
      'Existing Task PNG and comment text file upload; canonical refs, reload/read/download and Task image removal',
    ],
    excluded: [
      'native agents/inference',
      'logs or runtime readiness',
      'nonexistent add/remove relationship UI',
      'full Stage1',
      'visual signoff before screenshot review',
    ],
    sourceSha256: await fileDigest(import.meta.filename),
  };
  options.evidence.taskBoardUiProof = proof;
  if (group)
    proof.groupAssociation = {
      status: 'INCOMPLETE',
      ...group,
      fixtureReceipt: await json(join(options.root, 'ui-group-seed-receipt.json')),
      canonicalGroupReceipt: originalGroupReceipts[0],
    };
  const ui = createDesktopUiControls(cdp, {
    assertOwnedRenderer: options.assertOwnedRenderer,
    step,
  });
  const input = (
    method: 'Input.insertText' | 'Input.dispatchMouseEvent' | 'Input.dispatchKeyEvent',
    params: Record<string, unknown>
  ) => {
    options.assertOwnedRenderer();
    return cdp.send(method, params);
  };
  const waitProduct = async <T>(
    read: () => Promise<T>,
    matches: (value: T) => boolean,
    label: string
  ): Promise<T> => {
    const deadline = Date.now() + 20_000;
    while (Date.now() < deadline) {
      options.assertOwnedRenderer();
      const value = await read();
      if (matches(value)) return value;
      await pause();
    }
    throw new Error(`Task board product read timed out: ${label}; no mutation retry`);
  };
  const screenshot = async (name: string) => {
    options.assertOwnedRenderer();
    const capture = record(
      await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true })
    );
    assert.equal(typeof capture.data, 'string');
    const path = join(options.root, name);
    await writeFile(path, Buffer.from(String(capture.data), 'base64'), { mode: 0o600, flag: 'wx' });
    return { path, sha256: await fileDigest(path) };
  };
  // Expressions below only inspect current DOM. Input events remain the only UI actions.
  const measuredClick = async (expression: string, label: string, moveBeforePress = false) => {
    let point = record(await ui.waitRead(expression, label));
    if (point.dismissed === true) return false;
    if (moveBeforePress) {
      step({ action: 'mouseMoved', label, target: point });
      await input('Input.dispatchMouseEvent', {
        type: 'mouseMoved',
        x: point.x,
        y: point.y,
      });
      point = record(await ui.waitRead(expression, label + ' current target after pointer move'));
      if (point.dismissed === true) return false;
    }
    assert.equal(typeof point.x, 'number');
    assert.equal(typeof point.y, 'number');
    options.assertOwnedRenderer();
    step({ action: 'mouseClick', label, target: point, state: 'attempted' });
    await input('Input.dispatchMouseEvent', {
      type: 'mousePressed',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
    await input('Input.dispatchMouseEvent', {
      type: 'mouseReleased',
      x: point.x,
      y: point.y,
      button: 'left',
      clickCount: 1,
    });
    return true;
  };
  const selectOriginalAssignee = async (triggerExpression: string, optionExpression: string) => {
    for (let attempt = 1; attempt <= 2; attempt++) {
      await measuredClick(triggerExpression, 'open original assignee picker ' + attempt, true);
      if (
        await measuredClick(optionExpression, 'assign alice through original member option', true)
      )
        return;
      step({
        observation: 'owned assignee popup dismissed before any option press',
        attempt,
        navigation:
          attempt === 1 ? 'one known nonmutating reopen permitted' : 'stop before assignment',
      });
    }
    throw new Error(
      'Owned assignee popup dismissed twice before any option press; no assignment replay'
    );
  };
  const pointOf = (body: string) =>
    `(() => { const e=(()=>{${body}})();if(e?.dismissed===true)return e;if(!e)return null;const r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,hit=document.elementFromPoint(x,y);return r.width>0&&r.height>0&&hit&&(e===hit||e.contains(hit))&&!e.disabled?{x,y}:null; })()`;
  const card = (id: string) => `.kanban-task-card[data-task-id="${id}"]`;
  const receiptFor = async (
    operation: string,
    taskId: string,
    predicate: (payload: Record<string, unknown>) => boolean = () => true
  ) => {
    const found = await waitProduct(
      commands,
      (all) =>
        all.some((row) => {
          const command = record(row.command),
            payload = record(command.payload);
          return (
            ['completed', 'rejected'].includes(String(row.phase)) &&
            row.principalId === 'TEST-human' &&
            command.operation === operation &&
            payload.taskId === taskId &&
            predicate(payload)
          );
        }),
      operation
    );
    const matches = found.filter((row) => {
      const command = record(row.command),
        payload = record(command.payload);
      return (
        ['completed', 'rejected'].includes(String(row.phase)) &&
        row.principalId === 'TEST-human' &&
        command.operation === operation &&
        payload.taskId === taskId &&
        predicate(payload)
      );
    });
    assert.equal(matches.length, 1, 'exactly one business intent per actual control');
    return matches[0]!;
  };
  const readGroupSnapshot = (phase: string, taskIds: string[]) => {
    assert.ok(group);
    return readDesktopTaskBoardGroupSnapshot(cdp, {
      handleId: options.handleId, teamName, groupChatId: group.groupChatId,
      phase, taskIds, assertOwnedRenderer: options.assertOwnedRenderer,
    });
  };
  const selectGroupFilter = async (name: string) => {
    await ui.click('button[aria-label="Filter tasks"]', 'open original Task filters');
    await ui.click(
      'button[role="combobox"][aria-label="Group chat"]',
      'open original Group chat filter'
    );
    await ui.click('[role="option"]', 'choose original Group chat filter option', name);
    await ui.waitRead(
      `document.querySelector('button[role="combobox"][aria-label="Group chat"]')?.textContent.trim()===${desktopJsLiteral(name)}`,
      'original Group chat filter value'
    );
    await ui.click('button[aria-label="Filter tasks"]', 'close original Task filters');
    await ui.waitRead(
      `!document.querySelector('button[role="combobox"][aria-label="Group chat"]')`,
      'original Task filters closed'
    );
  };
  const before = await rows(taskDirectory);
  assert.equal(before.length, 1);
  assert.equal(before[0]!.id, options.seed.taskId);
  await ui.observeInput();
  await ui.clickSidebar(options.seed.subject);
  await ui.waitRead(
    `Boolean(document.querySelector(${desktopJsLiteral(card(options.seed.taskId))}))`,
    'canonical seed card'
  );
  proof.initialScreenshot = await screenshot('ui-task-board-initial.png');
  if (group) {
